{
  "findings": [
    {
      "title": "Dose reduction table inconsistent: Dose Level -1 and -2 values are swapped/incorrect",
      "page": 84,
      "quote": "Starting Dose 5.4 mg/kg, Dose Level -1 4.4 mg/kg, Dose Level -2 3.2 mg/kg",
      "severity": "critical"
    },
    {
      "title": "Dose delay window contradictory: 'up to 28 days' vs '49 days from last infusion'",
      "page": 84,
      "quote": "A dose can be delayed for up to 28 days (49 days from the last infusion date) from the planned date of administration.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.2.8 (pulmonary function tests)",
      "page": 73,
      "quote": "Pulmonary function tests (Section 8.2.8)",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.6.2 (new tumor sample)",
      "page": 74,
      "quote": "For patients who provide a new tumor sample, (Section 8.6.2)",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 6.6 (dose modification)",
      "page": 82,
      "quote": "follow the management guidance outlined in the dose modification section (Section 6.6).",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 8.3.4 (causality collection) from SAE variables",
      "page": 76,
      "quote": "Causality assessment in relation to other medication, as explained in Section 8.3.4",
      "severity": "major"
    },
    {
      "title": "Overdose definition contradictory: 'always serious' vs 'may be non-serious'",
      "page": 75,
      "quote": "Overdose is always serious. ... AEs can either be serious or non-serious.",
      "severity": "major"
    },
    {
      "title": "Pregnancy reporting window inconsistent: 7 months vs 4 months for female patients",
      "page": 80,
      "quote": "AstraZeneca must be notified of any female patients who becomes pregnant within 7 months of the last dose of study drug.",
      "severity": "major"
    },
    {
      "title": "Missing information: no definition of AESI or list of AESIs in protocol (only in text)",
      "page": 81,
      "quote": "the following events are considered to be AESIs: Interstitial Lung Disease/Pneumonitis ... LVEF decrease",
      "severity": "minor"
    },
    {
      "title": "Missing information: no statistical analysis section for AESI or ILD endpoints",
      "page": 81,
      "quote": "AESIs will be recorded on the eCRF using a recognized medical term or diagnosis that accurately reflects the event.",
      "severity": "minor"
    },
    {
      "title": "Missing information: no definition of 'safety follow-up' period for ILD (only 'until resolution')",
      "page": 74,
      "quote": "For ILD/pneumonitis, safety follow-up will be continued until resolution of the event.",
      "severity": "minor"
    },
    {
      "title": "Missing information: no reference to Appendix B for SAE definition in Section 8.3.11 (only 'see Appendix B')",
      "page": 79,
      "quote": "All SAEs have to be reported, whether or not considered causally related to the IP, or to the study procedure(s) (see Appendix B).",
      "severity": "minor"
    }
  ]
}
